17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Produces upper-case hexadecimal SHA-256 digests, the shared building block for the
25	 * deterministic identifiers derived from owner data (customer code, household id).
26	 */
27	public final class Sha256Hex {
28	
29	    private Sha256Hex() {
30	    }
31	
32	    /**
33	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest of
34	     *         {@code value}'s UTF-8 bytes.
35	     */
36	    public static String upperHexPrefix(String value, int length) {
37	        byte[] digest = sha256(value.getBytes(StandardCharsets.UTF_8));
38	        StringBuilder hex = new StringBuilder(digest.length * 2);
39	        for (byte b : digest) {
40	            hex.append(String.format("%02X", b));
41	        }
42	        return hex.substring(0, length);
43	    }
44	
45	    private static byte[] sha256(byte[] bytes) {
46	        try {
47	            return MessageDigest.getInstance("SHA-256").digest(bytes);
48	        }
49	        catch (NoSuchAlgorithmException ex) {
50	            throw new IllegalStateException("SHA-256 not available", ex);
51	        }
52	    }
53	}
