18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.util.Sha256Hex;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Produces the stable identifier shared by the members of a household. The identifier is the
25	 * first 12 hex characters of the SHA-256 digest of the household's {@link HouseholdKey}
26	 * ({@code normalizedLastName + "|" + postcode}), so every owner with the same last name and
27	 * postcode maps to the same value regardless of creation order.
28	 */
29	@Component
30	public class HouseholdIdGenerator {
31	
32	    /** Number of leading hex characters of the digest that form the household identifier. */
33	    private static final int HOUSEHOLD_ID_LENGTH = 12;
34	
35	    private final HouseholdKey householdKey;
36	
37	    public HouseholdIdGenerator(HouseholdKey householdKey) {
38	        this.householdKey = householdKey;
39	    }
40	
41	    /** @return the stable household identifier for {@code owner}, e.g. {@code "3F2A9C1E7B4D"}. */
42	    public String generate(Owner owner) {
43	        return Sha256Hex.upperHexPrefix(householdKey.of(owner), HOUSEHOLD_ID_LENGTH);
44	    }
45	}
