18	
19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Computes the canonical key that identifies an owner's household, namely the pair of last
26	 * name and postcode, joined as {@code normalizedLastName + "|" + postcode}. The last name is
27	 * compared case-insensitively and with runs of whitespace collapsed to a single space, so
28	 * cosmetic differences do not split a household; the postcode is taken verbatim. Two owners
29	 * belong to the same household exactly when their keys are equal, and the key is the input from
30	 * which {@link HouseholdIdGenerator} derives the stable household identifier.
31	 */
32	@Component
33	public class HouseholdKey {
34	
35	    /** @return the canonical household key for {@code owner}. */
36	    public String of(Owner owner) {
37	        return of(owner.getLastName(), owner.getPostcode());
38	    }
39	
40	    /** @return the canonical household key for the given last name and postcode. */
41	    public String of(String lastName, String postcode) {
42	        return normalize(lastName) + "|" + (postcode == null ? "" : postcode);
43	    }
44	
45	    /** Trim, collapse internal whitespace and lower-case, so equality ignores case and spacing. */
46	    private String normalize(String value) {
47	        if (value == null) {
48	            return "";
49	        }
50	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
51	    }
52	}
