18	
19	import java.util.Locale;
20	import java.util.Set;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Rejects an owner's email when its domain belongs to a known disposable-email provider.
26	 * An absent (null) email is accepted; the domain is compared case-insensitively.
27	 */
28	@Component
29	public class DisposableEmailDomainValidator {
30	
31	    /** Domains of disposable-email providers whose addresses are not accepted. */
32	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
33	        "mailinator.com", "tempmail.com", "guerrillamail.com");
34	
35	    /**
36	     * @param email the owner's email (may be {@code null}); expected already normalized
37	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
38	     */
39	    public void validate(String email) {
40	        if (email == null) {
41	            return;
42	        }
43	        int at = email.lastIndexOf('@');
44	        if (at < 0) {
45	            return;
46	        }
47	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
48	        if (BLOCKED_DOMAINS.contains(domain)) {
49	            throw new DisposableEmailDomainException(email);
50	        }
51	    }
52	}
