24	/**
25	 * Validates an optional owner postcode against the region of the owner's city. When present a
26	 * postcode must be exactly four digits and, for a city whose region is known, fall within that
27	 * region's inclusive range. A city with no known region accepts any 4-digit postcode. An absent
28	 * (null) postcode is left unvalidated, keeping the create contract backward-compatible.
29	 */
30	@Component
31	public class PostcodeValidator {
32	
33	    /** A postcode must be exactly four digits. */
34	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
35	
36	    /**
37	     * @param postcode the raw submitted postcode (may be {@code null})
38	     * @param city the owner's city, used to resolve the region that fixes the valid range
39	     * @throws InvalidPostcodeException if the postcode is present but not four digits, or is out of
40	     *         range for the region of the given city
41	     */
42	    public void validate(String postcode, String city) {
43	        if (postcode == null) {
44	            return;
45	        }
46	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
47	            throw new InvalidPostcodeException("Postcode must be four digits, but was: " + postcode);
48	        }
49	        int[] range = LocalityResolver.rangeForRegion(LocalityResolver.localityOf(city));
50	        if (range == null) {
51	            return;
52	        }
53	        int value = Integer.parseInt(postcode);
54	        if (value < range[0] || value > range[1]) {
55	            throw new InvalidPostcodeException(
56	                "Postcode " + postcode + " is out of range for city " + city);
57	        }
58	    }
59	}
