53	/**
54	 * Global Exception handler for REST controllers.
55	 * <p>
56	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
57	 *
58	 * @author Vitaliy Fedoriv
59	 * @author Alexander Dudkin
60	 */
61	@ControllerAdvice
62	public class ExceptionControllerAdvice {
63	
64	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
65	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
66	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
67	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
68	
69	    private final OwnerFieldsValidator ownerFieldsValidator;
70	
71	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
72	        this.ownerFieldsValidator = ownerFieldsValidator;
73	    }
74	
75	    /**
76	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
77	     * class.
78	     *
79	     * @param e     Object referring to the thrown exception.
80	     * @param status HTTP response status.
81	     * @param url URL request.
82	     */
83	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
84	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
85	        problemDetail.setType(URI.create(url.toString()));
86	        problemDetail.setTitle(e.getClass().getSimpleName());
87	        problemDetail.setDetail(detail);
88	        problemDetail.setProperty("timestamp", Instant.now());
89	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
90	        return problemDetail;
91	    }
92	
93	    /**
94	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
95	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
96	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
97	     * would catch it and report an authorization failure as a 500.
98	     *
99	     * @param e The {@link AccessDeniedException} to propagate
100	     * @throws AccessDeniedException always
101	     */
102	    @ExceptionHandler(AccessDeniedException.class)
103	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
104	        throw e;
105	    }
106	
107	    /**
108	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
109	     *
110	     * @param e The {@link Exception} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
113	     */
114	    @ExceptionHandler(Exception.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
117	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
118	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
119	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
120	        return ResponseEntity.status(status).body(detail);
121	    }
122	
123	    /**
124	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
125	     * method returns a 404 Not Found status if an entity does not exist.
126	     *
127	     * @param e The {@link DataIntegrityViolationException} to be handled
128	     * @param request {@link HttpServletRequest} object referring to the current request.
129	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
130	     */
131	    @ExceptionHandler(DataIntegrityViolationException.class)
132	    @ResponseBody
133	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
134	        logger.warn("Data integrity violation at {} {}: {}",
135	            request.getMethod(),
136	            request.getRequestURI(),
137	            e.getMessage());
138	        logger.debug("Data integrity violation stacktrace", e);
139	        HttpStatus status = HttpStatus.NOT_FOUND;
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
141	        return ResponseEntity.status(status).body(detail);
142	    }
143	
144	    /**
145	     * Handles exception thrown by Bean Validation on controller methods parameters
146	     *
147	     * @param e The {@link MethodArgumentNotValidException} to be handled
148	     * @param request {@link HttpServletRequest} object referring to the current request.
149	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
150	     */
151	    @ExceptionHandler(MethodArgumentNotValidException.class)
152	    @ResponseBody
153	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
154	        HttpStatus status = HttpStatus.BAD_REQUEST;
155	        BindingErrorsResponse errors = new BindingErrorsResponse();
156	        BindingResult bindingResult = e.getBindingResult();
157	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
158	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
159	            if (!missingFields.isEmpty()) {
160	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
161	            }
162	        }
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
164	        if (bindingResult.hasErrors()) {
165	            errors.addAllErrors(bindingResult);
166	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
167	                .map(fieldError -> {
168	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
169	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
170	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
171	                        fieldError.getField(),
172	                        defaultMessage,
173	                        rejectedValue);
174	                    return new ValidationMessageDto(message)
175	                        .putAdditionalProperty("field", fieldError.getField())
176	                        .putAdditionalProperty("rejectedValue", rejectedValue)
177	                        .putAdditionalProperty("defaultMessage", defaultMessage);
178	                })
179	                .toList();
180	            logger.debug("Validation error at {} {}: {}",
181	                request.getMethod(),
182	                request.getRequestURI(),
183	                bindingResult.getFieldErrors());
184	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
185	            return ResponseEntity.status(status).body(detail);
186	        }
187	        return ResponseEntity.status(status).body(detail);
188	    }
