177	    /**
178	     * Derives an owner's age band from its birth date measured against its registration
179	     * date, delegating to {@link AgeBandResolver}. Returns {@code null} when no birth date
180	     * is present.
181	     */
182	    default String formatAgeBand(Owner owner) {
